e demiri"]},{"id":"railing-defect","label":"Korkuluktaki sorun nedir?","options":["Kaynak koptu / sallanıyor","Paslanma ve çürüme var","Yükseklik uzatma / güçlendirme","Tamamen yenileme"]},{"id":"floor-level","label":"Kaçıncı kat seviyesinde?","options":["Zemin / Bahçe katı","1–3. kat","4. kat ve üzeri"]}]},"metal-kapi-mentese":{"serviceId":"metal-kapi-mentese","intro":"Metal kapı ve menteşe tamiratının detaylarını tanımlayalım.","questions":[{"id":"door-type","label":"Kapının cinsi nedir?","options":["Bina / Apartman giriş kapısı","Kazan dairesi / Sığınak kapısı","Yangın kapısı","Depo / Dükkan kepengi / kapısı"]},{"id":"hinge-issue","label":"Menteşe durumu nedir?","options":["Menteşe kaynak yerinden koptu","Menteşe aşındı / kapı yere sürtüyor","Hidrolik kapı kapatıcı bozuk","Kilit karşılığı oturmuyor"]},{"id":"electricity","label":"Çalışma alanında 220V elektrik prizi var mı?","options":["Evet, priz yakın","Usta uzatma kablosu getirsin"]}]},"ozel-demir-imalati":{"serviceId":"ozel-demir-imalati","intro":"Özel demir doğrama ve kaynak işinin detaylarını netleştirelim.","questions":[{"id":"project-type","label":"Ne tür bir demir imalatı yapılacak?","options":["Özel ölçü pencere/balkon demiri","Sundurma / Çatı demiri / Gölgelik","Metal raf / Masa iskeleti","Bahçe çiti / Kapı imalatı"]},{"id":"measurements","label":"Ölçüler ve tasarım hazır mı?","options":["Evet, yaklaşık ölçüler var","Usta yerinde keşif ve ölçü alsın","Çizim/fotoğraf üzerinden çalışılacak"]},{"id":"painting-needed","label":"Antipas ve boya uygulaması dahil mi?","options":["Evet, boyalı teslim edilsin","Hayır, sadece ham kaynak/montaj"]}]},"ev-temizligi":{"serviceId":"ev-temizligi","intro":"Süre ve ekip ihtiyacını belirlemek için evi kısaca tanımlayalım.","questions":[{"id":"home-size","label":"Evin oda düzeni nedir?","options":["1+0 / 1+1","2+1","3+1","4+1 veya daha büyük"]},{"id":"frequency","label":"Nasıl bir hizmet istiyorsunuz?","options":["Tek seferlik standart temizlik","Haftalık düzenli temizlik","İki haftada bir","Aylık periyodik temizlik"]},{"id":"supplies","label":"Temizlik malzemeleri hazır mı?","options":["Evet, evde malzemeler var","Temizlik görevlisi getirsin","Birlikte belirleyelim"]}]},"detayli-temizlik":{"serviceId":"detayli-temizlik","intro":"Detaylı ve dip köşe temizlik kapsamını belirleyelim.","questions":[{"id":"detail-focus","label":"Öncelikli detay alanları nelerdir?","options":["Mutfak dolap içleri & fırın/ocak","Banyo kireç temizliği & derz araları","Kapı, süpürgelik ve duvar silimi","Tüm evin dip köşe komple temizliği"]},{"id":"furnishing","label":"Evin eşya durumu nedir?","options":["Eşyalı ve yaşanılan ev","Yeni taşınılacak boş ev","Taşınma sonrası boş ev"]},{"id":"crew-preference","label":"Ekip büyüklüğü tercihi nedir?","options":["1 Kişi (Gündelik)","2 Kişilik Hızlı Ekip","Usta/Firma belirlesin"]}]},"tadilat-sonrasi-temizlik":{"serviceId":"tadilat-sonrasi-temizlik","intro":"İnşaat ve tadilat sonrası temizliğin yoğunluğunu belirleyelim.","questions":[{"id":"residue-type","label":"Alanın mevcut kirlilik durumu nedir?","options":["Boya damlaları & harç kalıntıları","İnce alçı tozu & zemin temizliği","Mutfak/Banyo montaj tozu","Kaba inşaat sonrası komple temizlik"]},{"id":"area-size","label":"Temizlenecek alanın yaklaşık metrekaresi?","options":["70 m² altı","70–120 m²","120–180 m²","180 m² üzeri"]},{"id":"industrial-vacuum","label":"Endüstriyel vakum ve kazıyıcı makine gerekli mi?","options":["Evet, profesyonel ekipman getirilsin","Standart ekipman yeterli"]}]},"cam-temizligi":{"serviceId":"cam-temizligi","intro":"Cam ve pencere temizliği kapsamını belirleyelim.","questions":[{"id":"window-scope","label":"Temizlenecek camların kapsamı nedir?","options":["Dairenin tüm standart pencereleri (3–6 cam)","Cam balkon / Katlanır cam sistemi","Geniş vitrin / Fransız balkon camları","Yalnızca 1–2 oda pencereleri"]},{"id":"safety-access","label":"Dıştan erişim ve güvenlik durumu nasıl?","options":["İçeriden kolayca silinebilir pencereler","Yüksek kat / dıştan erişim zorluğu var","Balkon demiri / korkuluk arkası"]},{"id":"frames-screens","label":"Pencere pervazları ve sineklikler silinsin mi?","options":["Evet, pervaz ve sineklikler dahil","Sadece cam yüzeyler"]}]}}$contract$::jsonb $$;
revoke all on function private.request_contract() from public, anon;
grant execute on function private.request_contract() to authenticated, service_role;

create or replace function private.request_answers_valid(p_service_id text, p_answers jsonb, p_complete boolean)
returns boolean language plpgsql immutable security invoker set search_path = ''
as $$
declare definition jsonb := private.request_contract()->p_service_id;
  question jsonb; visible_ids text[] := array[]::text[]; qid text; visible boolean;
begin
  if definition is null or jsonb_typeof(p_answers) is distinct from 'object' then return false; end if;
  for question in select value from jsonb_array_elements(definition->'questions') loop
    qid := question->>'id';
    visible := not (question ? 'showWhen') or (
      (question->'showWhen'->>'questionId') = any(visible_ids)
      and (question->'showWhen'->'equals') ? (p_answers->>(question->'showWhen'->>'questionId')));
    if coalesce(visible,false) then
      visible_ids := array_append(visible_ids,qid);
      if p_answers ? qid then
        if jsonb_typeof(p_answers->qid) <> 'string' or not ((question->'options') ? (p_answers->>qid)) then return false; end if;
      elsif p_complete then return false;
      end if;
    end if;
  end loop;
  return not exists(select 1 from jsonb_object_keys(p_answers) k where not (k=any(visible_ids)));
end $$;

create or replace function private.request_timing_days(value text)
returns integer language plpgsql immutable security invoker set search_path = ''
as $$ begin
  case value
    when 'urgent','Bugün / acil','Hemen / Bugün','Mümkün olan en kısa sürede' then return 0;
    when 'this_week','Bu hafta','Bu hafta içinde' then return 7;
    when 'next_two_weeks','Önümüzdeki iki hafta' then return 14;
    when 'flexible','Tarih konusunda esneğim','Tarih esnek' then return 30;
    else raise exception 'Invalid timing preference';
  end case;
end $$;
revoke all on function private.request_timing_days(text) from public,anon;
grant execute on function private.request_timing_days(text) to authenticated,service_role;

create or replace function private.normalize_request_timing()
returns trigger language plpgsql security invoker set search_path = ''
as $$ begin
  if new.preferred_timing is not null and trim(new.preferred_timing) <> '' then
    new.preferred_timing := case private.request_timing_days(new.preferred_timing)
      when 0 then 'urgent' when 7 then 'this_week'
      when 14 then 'next_two_weeks' else 'flexible' end;
  end if;
  return new;
end $$;
revoke all on function private.normalize_request_timing() from public,anon;
create trigger normalize_request_timing before insert or update of preferred_timing
on public.service_requests for each row execute function private.normalize_request_timing();

-- Preserve the existing function's ownership, authorization and query logic.
do $$ declare fn record; original text; updated text; replacements integer := 0;
begin
  for fn in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where p.proname='match_request' and n.nspname in ('public','private') loop
    original := pg_get_functiondef(fn.oid);
    updated := regexp_replace(original, 'horizon_days := case request_row.preferred_timing[\s\S]*?end;',
      'horizon_days := private.request_timing_days(request_row.preferred_timing);');
    if updated <> original then execute updated; replacements := replacements+1; end if;
  end loop;
  if replacements <> 1 then raise exception 'Expected exactly one matching implementation'; end if;
end $$;
commit;
